script:
const sym = { CNY: '¥', USD: '$' }
dsh.onData((data) => {
  const r = data.sources.balance
  if (!r) return
  const num = document.querySelector('.num'), state = document.querySelector('.state'), parts = document.querySelector('.parts')
  if (!r.ok) { num.textContent = '—'; state.textContent = ''; parts.innerHTML = '<span class="err">' + dsh.escape(r.error) + '</span>'; return }
  const info = (r.value.balance_infos || [])[0]
  if (!info) { num.textContent = '—'; return }
  const s = sym[info.currency] || info.currency + ' '
  num.textContent = s + Number(info.total_balance).toFixed(2)
  state.textContent = r.value.is_available ? '可用' : '余额不足'
  state.className = 'state' + (r.value.is_available ? '' : ' bad')
  parts.innerHTML = '<span>充值余额</span><b>' + s + dsh.escape(info.topped_up_balance) + '</b><span>赠送余额</span><b>' + s + dsh.escape(info.granted_balance) + '</b>'
})
